import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;

const COLORS = {
  bg: "#0A0A0A",
  accent: "#00B3E3",
  red: "#EF4444",
  darkGrey: "#2A2A2A",
  frozenGrey: "#1A1A1A",
  white: "#FFFFFF",
  mutedGrey: "#2A2A2A",
};

const TRANSITION = 8;

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ─── SCENE 1 ───────────────────────────────────────────────────────────────
// Bars spawn and fill screen. durationInFrames = 97 frames (~3.88s)

const BAR_HEIGHT = 4;
const BAR_SPACING = 16;
const BAR_WIDTH = 600;

// Seeded pseudo-random for deterministic output
function seededRandom(seed: number): number {
  const x = Math.sin(seed + 1) * 10000;
  return x - Math.floor(x);
}

interface BarConfig {
  id: number;
  spawnFrame: number;
  yOffset: number; // offset from center (in bar-row units, can be negative)
  fillDuration: number; // frames to fill from 0 to 100%
  xOffset: number; // slight horizontal variation
}

function generateBars(): BarConfig[] {
  const bars: BarConfig[] = [];
  let id = 0;

  // Phase 1: first bar at frame 0
  bars.push({ id: id++, spawnFrame: 0, yOffset: 0, fillDuration: 35, xOffset: 0 });

  // Phase 2: accelerating spawns
  // Bars spawn above and below center
  const totalFrames = 97;
  let currentFrame = 8;
  let spawnInterval = 10;
  let rowsAbove = 0;
  let rowsBelow = 0;
  let side = 1; // alternate above/below

  while (currentFrame < totalFrames - 5 && id < 160) {
    const seed = id * 7 + 13;
    const fillDuration = Math.round(20 + seededRandom(seed) * 30);
    const xOffset = (seededRandom(seed + 1) - 0.5) * 40;

    if (side > 0) {
      rowsBelow++;
      bars.push({
        id: id++,
        spawnFrame: currentFrame,
        yOffset: rowsBelow,
        fillDuration,
        xOffset,
      });
    } else {
      rowsAbove++;
      bars.push({
        id: id++,
        spawnFrame: currentFrame,
        yOffset: -rowsAbove,
        fillDuration,
        xOffset,
      });
    }

    side *= -1;
    spawnInterval = Math.max(1, spawnInterval - 0.15);
    currentFrame += Math.round(spawnInterval);
  }

  return bars;
}

const ALL_BARS = generateBars();

const Scene1: React.FC = () => {
  const frame = useCurrentFrame();
  const centerY = 2160 / 2;
  const centerX = 3840 / 2;

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg, fontFamily: "'Inter', sans-serif" }}>
      <svg width={3840} height={2160}>
        {ALL_BARS.map((bar) => {
          const localFrame = frame - bar.spawnFrame;
          if (localFrame < 0) return null;

          const fillProgress = Math.min(1, localFrame / bar.fillDuration);
          const barY = centerY + bar.yOffset * (BAR_HEIGHT + BAR_SPACING) - BAR_HEIGHT / 2;
          const barX = centerX - BAR_WIDTH / 2 + bar.xOffset;
          const filledWidth = fillProgress * BAR_WIDTH;

          // Fade in as they spawn
          const opacity = Math.min(1, localFrame / 5);

          return (
            <g key={bar.id} opacity={opacity}>
              {/* Track */}
              <rect
                x={barX}
                y={barY}
                width={BAR_WIDTH}
                height={BAR_HEIGHT}
                rx={2}
                fill="rgba(255,255,255,0.06)"
              />
              {/* Fill */}
              <rect
                x={barX}
                y={barY}
                width={filledWidth}
                height={BAR_HEIGHT}
                rx={2}
                fill="rgba(255,255,255,0.45)"
              />
            </g>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

// ─── SCENE 2 ───────────────────────────────────────────────────────────────
// All bars freeze and fade to dark grey. One turns blue. "50K views" label.
// durationInFrames = 175 frames (~7s)

const Scene2: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: videoFps } = useVideoConfig();
  const centerY = 2160 / 2;
  const centerX = 3840 / 2;

  // Fade-to-grey progress (0→1 over first 30 frames)
  const fadeToGrey = Math.min(1, frame / 30);

  // Blue bar: bar index ~60 (near center, slightly above)
  const BLUE_BAR_INDEX = 3; // using yOffset = -3 (3 rows above center)
  const blueBarY = centerY + (-3) * (BAR_HEIGHT + BAR_SPACING) - BAR_HEIGHT / 2;
  const blueBarX = centerX - BAR_WIDTH / 2 + 20;

  // Blue bar starts filling at frame 35
  const blueStartFrame = 35;
  const blueFillProgress = Math.min(1, Math.max(0, (frame - blueStartFrame) / 55));

  // Label fade in
  const labelProgress = spring({ frame, fps: videoFps, delay: 70, config: { damping: 200 } });
  const labelOpacity = labelProgress;
  const labelTranslate = interpolate(labelProgress, [0, 1], [20, 0]);

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg, fontFamily: "'Inter', sans-serif" }}>
      <svg width={3840} height={2160}>
        {ALL_BARS.map((bar) => {
          const isBlueBar = bar.yOffset === -3 && bar.id === ALL_BARS.find(b => b.yOffset === -3)?.id;
          const barY = centerY + bar.yOffset * (BAR_HEIGHT + BAR_SPACING) - BAR_HEIGHT / 2;
          const barX = centerX - BAR_WIDTH / 2 + bar.xOffset;

          if (isBlueBar) return null; // render blue bar separately

          // All bars frozen at their end state, fading to grey
          const frozenFill = bar.fillDuration < 30 ? 1 : 0.85;
          const trackOpacity = interpolate(fadeToGrey, [0, 1], [0.06, 0.04]);
          const fillOpacity = interpolate(fadeToGrey, [0, 1], [0.45, 0.08]);

          return (
            <g key={bar.id}>
              <rect x={barX} y={barY} width={BAR_WIDTH} height={BAR_HEIGHT} rx={2} fill={`rgba(26,26,26,${trackOpacity + 0.5})`} />
              <rect x={barX} y={barY} width={BAR_WIDTH * frozenFill} height={BAR_HEIGHT} rx={2} fill={`rgba(42,42,42,${fillOpacity + 0.2})`} />
            </g>
          );
        })}

        {/* Blue bar */}
        <rect x={blueBarX} y={blueBarY} width={BAR_WIDTH} height={BAR_HEIGHT} rx={2} fill="rgba(0,179,227,0.15)" />
        <rect
          x={blueBarX}
          y={blueBarY}
          width={blueFillProgress * BAR_WIDTH}
          height={BAR_HEIGHT}
          rx={2}
          fill={COLORS.accent}
        />
        {/* Glow on blue bar */}
        {blueFillProgress > 0.1 && (
          <rect
            x={blueBarX}
            y={blueBarY - 2}
            width={blueFillProgress * BAR_WIDTH}
            height={BAR_HEIGHT + 4}
            rx={3}
            fill={COLORS.accent}
            opacity={0.3}
            style={{ filter: "blur(4px)" }}
          />
        )}
      </svg>

      {/* 50K views label */}
      <div
        style={{
          position: "absolute",
          left: centerX + BAR_WIDTH / 2 + 40 + 20,
          top: blueBarY - 12,
          opacity: labelOpacity,
          transform: `translateX(${labelTranslate}px)`,
          display: "flex",
          alignItems: "center",
          gap: 16,
        }}
      >
        <div style={{ width: 2, height: 28, backgroundColor: COLORS.accent, opacity: 0.6 }} />
        <span
          style={{
            fontSize: 48,
            fontWeight: 700,
            color: COLORS.white,
            fontFamily: "'Inter', sans-serif",
            letterSpacing: "0.02em",
          }}
        >
          50K views
        </span>
      </div>
    </AbsoluteFill>
  );
};

// ─── SCENE 3 ───────────────────────────────────────────────────────────────
// Blue bar glows, then fades to grey. Opportunity missed.
// durationInFrames = 175 frames (~7s)

const Scene3: React.FC = () => {
  const frame = useCurrentFrame();
  const centerY = 2160 / 2;
  const centerX = 3840 / 2;

  const blueBarY = centerY + (-3) * (BAR_HEIGHT + BAR_SPACING) - BAR_HEIGHT / 2;
  const blueBarX = centerX - BAR_WIDTH / 2 + 20;

  // Glow expands: frames 0 → 37 (1.5s)
  const glowExpand = Math.min(1, frame / 37);
  // Glow contracts: frames 37 → 55
  const glowContract = Math.min(1, Math.max(0, (frame - 37) / 18));
  // Blue fades to grey: frames 37 → 112 (3s)
  const fadeFraction = Math.min(1, Math.max(0, (frame - 37) / 75));

  const blueColor = `rgb(${Math.round(0 + fadeFraction * 42)}, ${Math.round(179 - fadeFraction * 137)}, ${Math.round(227 - fadeFraction * 185)})`;
  const glowOpacity = interpolate(glowExpand, [0, 1], [0, 0.6]) * (1 - glowContract);
  const glowRadius = interpolate(glowExpand, [0, 1], [10, 80]) * (1 - glowContract * 0.7);

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg, fontFamily: "'Inter', sans-serif" }}>
      <svg width={3840} height={2160}>
        {/* All frozen grey bars */}
        {ALL_BARS.map((bar) => {
          const isBlueBar = bar.yOffset === -3 && bar.id === ALL_BARS.find(b => b.yOffset === -3)?.id;
          if (isBlueBar) return null;
          const barY = centerY + bar.yOffset * (BAR_HEIGHT + BAR_SPACING) - BAR_HEIGHT / 2;
          const barX = centerX - BAR_WIDTH / 2 + bar.xOffset;
          return (
            <g key={bar.id}>
              <rect x={barX} y={barY} width={BAR_WIDTH} height={BAR_HEIGHT} rx={2} fill="#1A1A1A" />
              <rect x={barX} y={barY} width={BAR_WIDTH * 0.85} height={BAR_HEIGHT} rx={2} fill="#2A2A2A" />
            </g>
          );
        })}

        {/* Glow effect */}
        <ellipse
          cx={blueBarX + BAR_WIDTH / 2}
          cy={blueBarY + BAR_HEIGHT / 2}
          rx={BAR_WIDTH / 2 + glowRadius * 4}
          ry={glowRadius * 2.5}
          fill={COLORS.accent}
          opacity={glowOpacity * 0.25}
          style={{ filter: `blur(${glowRadius * 0.8}px)` }}
        />

        {/* Blue bar fading to grey */}
        <rect x={blueBarX} y={blueBarY - 2} width={BAR_WIDTH} height={BAR_HEIGHT + 4} rx={3} fill={blueColor} opacity={0.3 * (1 - fadeFraction)} style={{ filter: "blur(4px)" }} />
        <rect x={blueBarX} y={blueBarY} width={BAR_WIDTH} height={BAR_HEIGHT} rx={2} fill={blueColor} />
      </svg>
    </AbsoluteFill>
  );
};

// ─── SCENE 4 ───────────────────────────────────────────────────────────────
// A bar turns red, spreads to neighbors. ~60% red by end.
// durationInFrames = 165 frames (~6.6s)

const Scene4: React.FC = () => {
  const frame = useCurrentFrame();
  const centerY = 2160 / 2;
  const centerX = 3840 / 2;

  // Origin bar: lower-left area
  const ORIGIN_Y_OFFSET = 8;
  const ORIGIN_X_INDEX = 0;

  // For each bar, calculate distance from origin to determine when it turns red
  // Spread speed: each "distance unit" takes 3 frames
  const SPREAD_SPEED = 2.5; // frames per distance unit

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg, fontFamily: "'Inter', sans-serif" }}>
      <svg width={3840} height={2160}>
        {ALL_BARS.map((bar) => {
          const barY = centerY + bar.yOffset * (BAR_HEIGHT + BAR_SPACING) - BAR_HEIGHT / 2;
          const barX = centerX - BAR_WIDTH / 2 + bar.xOffset;

          // Distance from origin (in bar-row units)
          const dyDist = Math.abs(bar.yOffset - ORIGIN_Y_OFFSET);
          const dxDist = Math.abs(bar.xOffset - (-60)) / 40; // rough x distance
          const dist = dyDist + dxDist;
          const redStartFrame = dist * SPREAD_SPEED + 5;

          const isRed = frame >= redStartFrame;
          const redProgress = Math.min(1, Math.max(0, (frame - redStartFrame) / 5));

          const fillColor = isRed
            ? `rgb(${Math.round(42 + redProgress * (239 - 42))}, ${Math.round(42 + redProgress * (68 - 42))}, ${Math.round(42 + redProgress * (68 - 42))})`
            : "#2A2A2A";
          const trackFill = isRed ? "rgba(239,68,68,0.08)" : "#1A1A1A";

          return (
            <g key={bar.id}>
              <rect x={barX} y={barY} width={BAR_WIDTH} height={BAR_HEIGHT} rx={2} fill={trackFill} />
              <rect x={barX} y={barY} width={BAR_WIDTH * 0.85} height={BAR_HEIGHT} rx={2} fill={fillColor} />
            </g>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

// ─── SCENE 5 ───────────────────────────────────────────────────────────────
// Hard cut to black. Line draws. "YouTube Scraper" + "by Apify" fade in. Line pulses.
// durationInFrames = 135 frames (~5.4s)

const Scene5: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: videoFps } = useVideoConfig();

  // 0.3s pause = 7.5 frames → start at frame 8
  const lineStart = 8;
  // Line draws over 1.2s = 30 frames
  const lineProgress = Math.min(1, Math.max(0, (frame - lineStart) / 30));
  const lineWidth = lineProgress * 3840;

  // Title fade in
  const titleProgress = spring({ frame, fps: videoFps, delay: 38, config: { damping: 200 } });
  const titleOpacity = titleProgress;
  const titleTranslate = interpolate(titleProgress, [0, 1], [40, 0]);

  // Subtitle fade in
  const subProgress = spring({ frame, fps: videoFps, delay: 50, config: { damping: 200 } });
  const subOpacity = subProgress;
  const subTranslate = interpolate(subProgress, [0, 1], [30, 0]);

  // Pulse: single pulse at frame 80
  const pulseFrame = Math.max(0, frame - 80);
  const pulseOpacity = Math.max(0, 1 - pulseFrame / 20);
  const pulseWidth = interpolate(pulseFrame, [0, 20], [2, 8]);

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg, fontFamily: "'Inter', sans-serif" }}>
      {/* Line */}
      <div
        style={{
