        }}
      />
      {/* Pulse glow on line */}
      {pulseOpacity > 0 && (
        <div
          style={{
            position: "absolute",
            top: 2160 / 2 - pulseWidth / 2,
            left: 0,
            width: 3840,
            height: pulseWidth,
            backgroundColor: COLORS.accent,
            borderRadius: pulseWidth / 2,
            opacity: pulseOpacity * 0.5,
