            fontFamily: "'Inter', sans-serif",
          }}
        >
          YouTube Scraper
        </span>
      </div>

      {/* Subtitle */}
      <div
        style={{
          position: "absolute",
          top: 2160 / 2 + 60,
          left: 0,
          right: 0,
          textAlign: "center",
          opacity: subOpacity,
          transform: `translateY(${subTranslate}px)`,
        }}
      >
        <span
          style={{
            fontSize: 64,
            fontWeight: 600,
            color: COLORS.accent,
            letterSpacing: "0.05em",
            fontFamily: "'Inter', sans-serif",
          }}
        >
          by Apify
        </span>
      </div>
    </AbsoluteFill>
  );
};

// ─── SCENE 6 ───────────────────────────────────────────────────────────────
// Title slides up/shrinks. Bars stream in, some caught by blue line, stack on right.
// durationInFrames = 210 frames (~8.4s) + hold

interface StreamBar {
  id: number;
  spawnFrame: number;
  yPos: number; // absolute Y
  speed: number; // px per frame
  isCaught: boolean;
  catchX: number; // X position where it hits the line (center = 1920)
}

function generateStreamBars(): StreamBar[] {
  const bars: StreamBar[] = [];
  const lineX = 3840 / 2;

  for (let i = 0; i < 80; i++) {
    const seed = i * 13 + 7;
    const spawnFrame = 20 + Math.round(seededRandom(seed) * 180);
    const yPos = 400 + seededRandom(seed + 1) * 1360; // vertical spread
    const speed = 8 + seededRandom(seed + 2) * 14; // px/frame
    const isCaught = seededRandom(seed + 3) < 0.30; // 30% caught

    bars.push({
      id: i,
      spawnFrame,
      yPos,
      speed,
      isCaught,
      catchX: lineX,
    });
  }

  return bars;
}

const STREAM_BARS = generateStreamBars();
const STREAM_BAR_WIDTH = 200;
const STACK_X = 3840 - 500;
const STACK_START_Y = 500;
const STACK_SPACING = 32;
const LABELS = ["mention", "creator", "data point"];

const Scene6: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: videoFps } = useVideoConfig();
  const lineX = 3840 / 2;

  // Title slides up and shrinks
  const titleShift = spring({ frame, fps: videoFps, delay: 0, config: { damping: 200 } });
  const titleY = interpolate(titleShift, [0, 1], [2160 / 2 - 140, 120]);
  const titleSize = interpolate(titleShift, [0, 1], [144, 72]);
  const titleOpacity = titleShift;

  const subShift = spring({ frame, fps: videoFps, delay: 5, config: { damping: 200 } });
  const subY = interpolate(subShift, [0, 1], [2160 / 2 + 60, 230]);
  const subSize = interpolate(subShift, [0, 1], [64, 40]);
  const subOpacity = subShift;

  // Blue line stays centered
  const lineAppear = spring({ frame, fps: videoFps, delay: 8, config: { damping: 200 } });

  // Track caught bars in order for stacking
  let caughtCount = 0;

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg, fontFamily: "'Inter', sans-serif" }}>
      {/* Blue line */}
      <div
        style={{
          position: "absolute",
          top: 2160 / 2 - 1,
          left: 0,
          right: 0,
          height: 2,
          backgroundColor: COLORS.accent,
          opacity: lineAppear,
          boxShadow: `0 0 16px ${COLORS.accent}, 0 0 32px rgba(0,179,227,0.3)`,
        }}
      />

      {/* Streaming bars */}
      {STREAM_BARS.map((bar) => {
        const localFrame = frame - bar.spawnFrame;
        if (localFrame < 0) return null;

        const startX = -STREAM_BAR_WIDTH - 50;
        const rawX = startX + localFrame * bar.speed;

        // If caught: bar travels to lineX, then snaps to stack
        if (bar.isCaught) {
          const stackIndex = caughtCount;
          caughtCount++;

          const framesTo = (lineX - startX) / bar.speed;
          const stackY = STACK_START_Y + stackIndex * STACK_SPACING;

          if (localFrame < framesTo) {
            // Still traveling
            const x = startX + localFrame * bar.speed;
            return (
              <g key={bar.id}>
                <rect x={x} y={bar.yPos} width={STREAM_BAR_WIDTH} height={BAR_HEIGHT} rx={2} fill="#2A2A2A" />
              </g>
            );
          } else {
            // Caught: flash white then turn blue, animate to stack
            const postCatch = localFrame - framesTo;
            const snapProgress = Math.min(1, postCatch / 12);

            const catchFlash = Math.max(0, 1 - postCatch / 6);
            const barColor = catchFlash > 0.5 ? COLORS.white : COLORS.accent;

            const currentX = interpolate(snapProgress, [0, 1], [lineX - STREAM_BAR_WIDTH / 2, STACK_X]);
            const currentY = interpolate(snapProgress, [0, 1], [bar.yPos, stackY]);

            // Label
            const labelDelay = framesTo + 15;
            const labelProgress = Math.min(1, Math.max(0, (localFrame - labelDelay) / 10));

            return (
              <g key={bar.id}>
                <rect x={currentX} y={currentY} width={STREAM_BAR_WIDTH} height={BAR_HEIGHT} rx={2} fill={barColor} />
                {stackIndex < 3 && labelProgress > 0 && (
                  <text
                    x={STACK_X + STREAM_BAR_WIDTH + 24}
                    y={stackY + BAR_HEIGHT / 2 + 8}
                    fill={COLORS.white}
                    fontSize={36}
                    fontFamily="'Inter', sans-serif"
                    fontWeight={600}
                    opacity={labelProgress}
                  >
                    {LABELS[stackIndex]}
                  </text>
                )}
              </g>
            );
          }
        } else {
          // Not caught: pass through
          const x = rawX;
          if (x > 3840 + STREAM_BAR_WIDTH) return null;

          // Flash white briefly when crossing line
          const frameAtLine = (lineX - startX) / bar.speed;
          const distFromLine = localFrame - frameAtLine;
          const crossFlash = Math.abs(distFromLine) < 2 ? Math.max(0, 1 - Math.abs(distFromLine) * 0.5) : 0;
          const barOpacity = Math.max(0, 1 - (x - 3200) / 600);
          const barColor = crossFlash > 0 ? `rgba(255,255,255,${0.3 + crossFlash * 0.4})` : "#2A2A2A";

          return (
            <g key={bar.id} opacity={barOpacity}>
              <rect x={x} y={bar.yPos} width={STREAM_BAR_WIDTH} height={BAR_HEIGHT} rx={2} fill={barColor} />
            </g>
          );
        }
      })}

      {/* Title text */}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: titleY,
          textAlign: "center",
          opacity: titleOpacity,
        }}
      >
        <span
          style={{
            fontSize: titleSize,
            fontWeight: 700,
            color: COLORS.white,
            letterSpacing: "-0.02em",
            fontFamily: "'Inter', sans-serif",
          }}
        >
          YouTube Scraper
        </span>
      </div>

      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: subY,
          textAlign: "center",
          opacity: subOpacity,
        }}
      >
        <span
          style={{
            fontSize: subSize,
            fontWeight: 600,
            color: COLORS.accent,
            letterSpacing: "0.05em",
            fontFamily: "'Inter', sans-serif",
          }}
        >
          by Apify
        </span>
      </div>
    </AbsoluteFill>
  );
};

// ─── DURATIONS ─────────────────────────────────────────────────────────────
const S1_DUR = 100;
const S2_DUR = 178;
const S3_DUR = 178;
const S4_DUR = 168;
const S5_DUR = 138;
const S6_DUR = 218;
const OPEN_DUR = 20;
const CLOSE_DUR = 25;

// Total = sum - (num_transitions * TRANSITION)
// Transitions: open→s1, s1→s2, s2→s3, s3→s4, s4→s5, s5→s6, s6→close = 7
export const durationInFrames =
  OPEN_DUR + S1_DUR + S2_DUR + S3_DUR + S4_DUR + S5_DUR + S6_DUR + CLOSE_DUR -
  7 * TRANSITION;

// ─── MAIN COMPOSITION ──────────────────────────────────────────────────────

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      {/* Opening black */}
      <TransitionSeries.Sequence durationInFrames={OPEN_DUR}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 1: Bars spawning */}
      <TransitionSeries.Sequence durationInFrames={S1_DUR + TRANSITION}>
        <Scene1 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 2: Blue bar + 50K label */}
      <TransitionSeries.Sequence durationInFrames={S2_DUR + TRANSITION}>
        <Scene2 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 3: Glow and fade */}
      <TransitionSeries.Sequence durationInFrames={S3_DUR + TRANSITION}>
        <Scene3 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 4: Red spread */}
      <TransitionSeries.Sequence durationInFrames={S4_DUR + TRANSITION}>
        <Scene4 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 5: YouTube Scraper reveal */}
      <TransitionSeries.Sequence durationInFrames={S5_DUR + TRANSITION}>
        <Scene5 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 6: Filter system */}
      <TransitionSeries.Sequence durationInFrames={S6_DUR + TRANSITION}>
        <Scene6 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Closing black */}
      <TransitionSeries.Sequence durationInFrames={CLOSE_DUR}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
